def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        nanoseconds = int(nanoseconds)
    except ValueError:
        raise ValueError("Invalid nanoseconds value: {}".format(nanoseconds))
    if tz is not None:
        try:
            tz = pytz.timezone(tz)
        except pytz.UnknownTimeZoneError:
            raise ValueError("Invalid time zone: {}".format(tz))
    return Time(nanoseconds, tz)

def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """
    try:
        return {
            "days": value.days,
            "seconds": value.seconds,
            "microseconds": value.microseconds,
        }
    except AttributeError:
        raise TypeError("Invalid type for dehydration: {}".format(type(value))) from None

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if not isinstance(value, Time):
        raise TypeError("Expected Time object, got {}".format(type(value)))
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise TypeError("Value must be a Point")

    return {
        "x": value.x,
        "y": value.y,
        "z": value.z
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        return list(self.data.keys())
    except AttributeError:
        return []

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._get_handler_class(version) for version in cls._supported_versions}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if protocol_version not in cls._supported_versions:
            return {}
        return {protocol_version: cls._get_handler_class(protocol_version)}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self.keys.index(key)
    except ValueError:
        return -1

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not keys:
        return list(self.values())
    else:
        return [self.values()[key] for key in keys]

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    if not keys:
        return self._data

    result = {}
    for key in keys:
        try:
            result[key] = self._data[key]
        except KeyError:
            result[key] = None

    return result

def round_half_to_even(n):
    """
    Round a number to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    if n % 2 == 0:
        return n
    else:
        return n + 1

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class PointSubclass(Point):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            self.name = name
            self.fields = fields
            self.srid_map = srid_map

        def __str__(self):
            return f"{self.name}({', '.join(self.fields)})"

        def __repr__(self):
            return f"{self.name}({', '.join(self.fields)})"

        def __eq__(self, other):
            return self.name == other.name and self.fields == other.fields and self.srid_map == other.srid_map

        def __ne__(self, other):
            return not self.__eq__(other)

        def __hash__(self):
            return hash((self.name, self.fields, self.srid_map))

    return PointSubclass

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning)
            return func(*args, **kwargs)
        return wrapper
    return decorator

