def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 3,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == -1:
        return d1
    else:
        result = {}
        for key, value in d1.items():
            if key not in d2 or d2[key] != value:
                result[key] = value
        for key, value in d2.items():
            if key not in d1 or d1[key] != value:
                result[key] = value
        return result

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple) or len(coord) != 2:
        raise ValueError("Coordinate must be a tuple of length 2")
    if not isinstance(weight, (int, float)):
        raise ValueError("Weight must be a number")
    if weight <= 0:
        raise ValueError("Weight must be positive")

    x, y = coord
    if x < 0 or x >= self.width or y < 0 or y >= self.height:
        return

    self.data[x][y] += weight

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field, value in observer_schema.items():
        if field not in last_applied_manifest:
            last_applied_manifest[field] = value
        elif isinstance(value, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], value, response[field])
        else:
            last_applied_manifest[field] = response[field]

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Step 1: Extract the Kubernetes resources from the application manifest
    resources = app.spec.manifest.resources

    # Step 2: Iterate over each resource and generate a default observer schema
    for resource in resources:
        # Step 3: Check if a custom observer schema has been specified for the resource
        if resource.spec.observer_schema is not None:
            continue

        # Step 4: Generate a default observer schema for the resource
        observer_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": "object",
                    "properties": {
                        "observedGeneration": {
                            "type": "integer"
                        },
                        "conditions": {
                            "type": "array",
                            "items": {
                                "type": "object",
                                "properties": {
                                    "type": {
                                        "type": "string"
                                    },
                                    "status": {
                                        "type": "string"
                                    },
                                    "lastTransitionTime": {
                                        "type": "string",
                                        "format": "date-time"
                                    },
                                    "reason": {
                                        "type": "string"
                                    },
                                    "message": {
                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "type",
                                    "status",
                                    "lastTransitionTime",
                                    "reason",
                                    "message"
                                ]
                            }
                        }
                    },
                    "required": [
                        "observedGeneration",
                        "conditions"
                    ]
                }
            },
            "required": [
                "status"
            ]
        }

        # Step 5: Add the default observer schema to the resource
        resource.spec.observer_schema = observer_schema

    # Step 6: Return the updated application
    return app

def validate(self, path):
