def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Step 1: Extract the digests from the manifest files
    manifest_digests = set()
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as f:
            manifest_digests.update(re.findall(r'sha256:[a-f0-9]{64}', f.read()))

    # Step 2: Check if all digests in manifest are present in digests_used
    for digest in manifest_digests:
        if digest not in digests_used:
            raise ValueError(f'Digest {digest} is not present in digests_used')

    # Step 3: Check if all digests in digests_used are present in manifest
    for digest in digests_used:
        if digest not in manifest_digests:
            raise ValueError(f'Digest {digest} is not present in manifest')

    # Step 4: Check if all digests in manifest are used in digests_used
    for digest in manifest_digests:
        if digest not in digests_used:
            raise ValueError(f'Digest {digest} is not used in digests_used')

    # Step 5: Check if all digests in digests_used are used in manifest
    for digest in digests_used:
        if digest not in manifest_digests:
            raise ValueError(f'Digest {digest} is not used in manifest')

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for file in inventory:
        if file.version == version:
            logical_path = file.logical_path
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(file.content_file)
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Check if the fixity block has a 'fixity' key
    if 'fixity' not in fixity:
        raise ValueError("Fixity block must have a 'fixity' key")

    # Check if the 'fixity' key is a list
    if not isinstance(fixity['fixity'], list):
        raise ValueError("'fixity' key must be a list")

    # Check if all items in the 'fixity' list are dictionaries
    for item in fixity['fixity']:
        if not isinstance(item, dict):
            raise ValueError("All items in the 'fixity' list must be dictionaries")

    # Check if all dictionaries in the 'fixity' list have a 'file' key
    for item in fixity['fixity']:
        if 'file' not in item:
            raise ValueError("All dictionaries in the 'fixity' list must have a 'file' key")

    # Check if all 'file' keys in the 'fixity' list are strings
    for item in fixity['fixity']:
        if not isinstance(item['file'], str):
            raise ValueError("All 'file' keys in the 'fixity' list must be strings")

    # Check if all files referenced in the 'fixity' list are present in the manifest
    for item in fixity['fixity']:
        if item['file'] not in manifest_files:
            raise ValueError(f"File '{item['file']}' referenced in the 'fixity' list is not present in the manifest")

    # Check if the 'fixity' block has a 'algorithm' key
    if 'algorithm' not in fixity:
        raise ValueError("Fixity block must have a 'algorithm' key")

    # Check if the 'algorithm' key is a string
    if not isinstance(fixity['algorithm'], str):
        raise ValueError("'algorithm' key must be a string")

    # Check if the 'algorithm' key is a supported algorithm
    supported_algorithms = ['md5', 'sha1', 'sha256']
    if fixity['algorithm'] not in supported_algorithms:
        raise ValueError(f"Unsupported algorithm '{fixity['algorithm']}'")

    # Check if the 'fixity' block has a 'value' key
    if 'value' not in fixity:
        raise ValueError("Fixity block must have a 'value' key")

    # Check if the 'value' key is a string
    if not isinstance(fixity['value'], str):
        raise ValueError("'value' key must be a string")

    # Check if the 'value' key is a valid checksum
    if fixity['algorithm'] == 'md5':
        if not re.match(r'^[a-fA-F0-9]{32}$', fixity['value']):
            raise ValueError("Invalid MD5 checksum")
    elif fixity['algorithm'] == 'sha1':
        if not re.match(r'^[a-fA-F0-9]{40}$', fixity['value']):
            raise ValueError("Invalid SHA1 checksum")
    elif fixity['algorithm'] == 'sha256':
        if not re.match(r'^[a-fA-F0-9]{64}$', fixity['value']):
            raise ValueError("Invalid SHA256 checksum")

    # Check if the 'fixity' block has a 'timestamp' key
    if 'timestamp' not in fixity:
        raise ValueError("Fixity block must have a 'timestamp' key")

    # Check if the 'timestamp' key is a string
    if not isinstance(fixity['timestamp'], str):
        raise ValueError("'timestamp' key must be a string")

    # Check if the 'timestamp' key is a valid ISO 8601 timestamp
    try:
        datetime.datetime.fromisoformat(fixity['timestamp'])
    except ValueError:
        raise ValueError("Invalid ISO 8601 timestamp")

    # Check if the 'fixity' block has a 'source' key
    if 'source' not in fixity:
        raise ValueError("Fixity block must have a 'source' key")

    # Check if the 'source' key is a string
    if not isinstance(fixity['source'], str):
        raise ValueError("'source' key must be a string")

    # Check if the 'source' key is a valid URL
    try:
        urlparse(fixity['source'])
    except ValueError:
        raise ValueError("Invalid URL")

    # Check if the 'fixity' block has a 'status' key
    if 'status' not in fixity:
        raise ValueError("Fixity block must have a 'status' key")

    # Check if the 'status' key is a string
    if not isinstance(fixity['status'], str):
        raise ValueError("'status' key must be a string")

    # Check if the 'status' key is a valid status code
