def files_list(path):
    """
    Return the files in `path`
    """
    files = []
    for file in os.listdir(path):
        if os.path.isfile(os.path.join(path, file)):
            files.append(file)
    return files

def files_list_from_zipfile(zip_path):
    """
    Return the files in `zip_path`
    """
    with zipfile.ZipFile(zip_path) as zip_file:
        return zip_file.namelist()

def fix_namespace_prefix_w(content):
    """
    Convert textos cujo padrão é `w:st="` em `w-st="`
    """
    # Verify that the input is a string
    if not isinstance(content, str):
        raise TypeError("The input must be a string")

    # Replace all occurrences of `w:st="` with `w-st="`
    return content.replace("w:st=", "w-st=")

def match_pubdate(node, pubdate_xpaths):
    """
    Returns the first match from the list of pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        match = node.xpath(xpath)
        if match:
            return match[0]
    return None

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if expr.op == '&':
            if expr.left.op == '|' and expr.left.right == expr.right:
                result.append(expr.left.left)
            elif expr.right.op == '|' and expr.right.right == expr.left:
                result.append(expr.right.left)
        elif expr.op == '|':
            if expr.left.op == '&' and expr.left.right == expr.right:
                result.append(expr.left.left)
            elif expr.right.op == '&' and expr.right.right == expr.left:
                result.append(expr.right.left)
        else:
            result.append(expr)
    return result

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        return namefunc().encode('utf-8')
    except AttributeError:
        return namefunc()

