def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    if style not in ["semver", "pep440"]:
        raise ValueError("style must be either 'semver' or 'pep440'")

    if style == "semver":
        return ".".join(str(piece) for piece in pieces)
    elif style == "pep440":
        return ".".join(str(piece) for piece in pieces) + ".dev0"
    else:
        raise ValueError("Invalid style")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if "+" in pieces:
        return "."
    else:
        return "+"

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not isinstance(args, (list, tuple)):
        args = [args]
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ.copy()
    for command in commands:
        if verbose:
            print(f"Running command: {command}")
        try:
            result = subprocess.run(
                command,
                args=args,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                universal_newlines=True,
            )
            if hide_stderr:
                result.stderr = ""
            if result.returncode != 0:
                raise RuntimeError(f"Command {command} failed with exit code {result.returncode}")
            return result.stdout
        except FileNotFoundError:
            raise RuntimeError(f"Command {command} not found")
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Command {command} failed with exit code {e.returncode}")

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def wrapper(*args, **kwargs):
        try:
            method(*args, **kwargs)
        except Exception as e:
            print(f"Error handling VCS {vcs}: {e}")
    return wrapper

