def size_to_bytes(size: str) -> int:
    """
    Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    try:
        size = size.upper()
        if size.endswith("K"):
            return int(size[:-1]) * 1000
        elif size.endswith("M"):
            return int(size[:-1]) * 1000000
        elif size.endswith("G"):
            return int(size[:-1]) * 1000000000
        elif size.endswith("T"):
            return int(size[:-1]) * 1000000000000
        else:
            return int(size)
    except ValueError:
        raise ValueError("Invalid size format")

def _dictsum(dicts):
    result = {}
    for d in dicts:
        for key, value in d.items():
            if key not in result:
                result[key] = value
            else:
                result[key] += value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    # Check if url is a string
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    # Check if url_args is a dict
    if not isinstance(url_args, dict):
        raise TypeError("url_args must be a dict")

    # Replace any custom string URL items with values in args
    for key, value in url_args.items():
        url = url.replace("{" + key + "}", value)

    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if not isinstance(val, str):
        raise ValueError("Input must be a string")
    return val.lower() in ("none", "null", "nil")

