    # Check if the function has any decorators
    if not inspect.getdecorators(func):
        raise ValueError("The function must have decorators")

    # Check if the function has any annotations
    if not inspect.getannotations(func):
        raise ValueError("The function must have annotations")

    # Check if the function has any docstring
    if not inspect.getdoc(func):
        raise ValueError("The function must have a docstring")

    # Check if the function has any parameters
    if not inspect.signature(func).parameters:
        raise ValueError("The function must have parameters")

    # Check if the function has any return value
    if not inspect.signature(func).return_annotation:
        raise ValueError("The function must have a return value")

    # Check if the function has any side effects
    if not inspect.getsource(func):
        raise ValueError("The function must have a source code")

    # Check if the function has any dependencies
    if not inspect.getclosurevars(func):
        raise ValueError("The function must have dependencies")

    # Check if the function has any nested functions
    if not inspect.getinnerfunctions(func):
        raise ValueError("The function must have nested functions")

    # Check if the function has any decorators
    if not inspect.getdecorators(func):
        raise ValueError("The function must have decorators")

    # Check if the function has any annotations
    if not inspect.getannotations(func):
        raise ValueError("The function must have annotations")

    # Check if the function has any docstring
    if not inspect.getdoc(func):
        raise ValueError("The function must have a docstring")

    # Check if the function has any parameters
    if not inspect.signature(func).parameters:
        raise ValueError("The function must have parameters")

    # Check if the function has any return value
    if not inspect.signature(func).return_annotation:
        raise ValueError("The function must have a return value")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("Pattern must be a string")
    if strip:
        pattern = pattern.strip()
    try:
        return re.compile(pattern)
    except re.error:
        raise ValueError("Invalid regex pattern")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ.copy()
    for command in commands:
        try:
            subprocess.check_call(command, args=args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print(e.output.decode("utf-8"), end="")
            else:
                print(e.output.decode("utf-8"), file=sys.stderr, end="")
            if verbose:
                print(f"Command '{command}' failed with exit code {e.returncode}.", file=sys.stderr)
            return e.returncode
        except OSError as e:
            if hide_stderr:
                print(e.strerror, end="")
            else:
                print(e.strerror, file=sys.stderr, end="")
            if verbose:
                print(f"Command '{command}' failed with error {e.errno}.", file=sys.stderr)
            return e.errno
    return 0

def is_ipv4(target):
