def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2) ** 2) / (2 * (0.1 ** 2)))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as f:
                config = yaml.safe_load(f)
                configs[config_filename] = config
        except FileNotFoundError:
            errors.append(logging.LogRecord(logging.ERROR, 'Configuration file not found: {}'.format(config_filename)))
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(logging.ERROR, 'Error parsing configuration file: {}'.format(config_filename)))

    if overrides:
        for key, value in overrides.items():
            for config_filename, config in configs.items():
                if key in config:
                    config[key] = value

    if resolve_env:
        for config_filename, config in configs.items():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    env_var = value[1:]
                    if env_var in os.environ:
                        config[key] = os.environ[env_var]

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._get_handler_class(version) for version in cls._supported_versions}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed in a tuple")
        if protocol_version not in cls._supported_versions:
            return {}
        return {protocol_version: cls._get_handler_class(protocol_version)}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    bookmarks = []
    for value in values:
        try:
            bookmark = Bookmark.from_raw_value(value)
            bookmarks.append(bookmark)
        except ValueError:
            pass
    return Bookmarks(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if not isinstance(seq, collections.abc.Sequence):
        raise TypeError("seq must be a sequence")
    if bufsize is not None and not isinstance(bufsize, int):
        raise TypeError("bufsize must be an integer")

    if isinstance(seq, str):
        return (seq, str)
    elif isinstance(seq, bytes):
        return (seq, bytes)
    elif isinstance(seq, bytearray):
        return (seq, bytearray)
    elif isinstance(seq, memoryview):
        return (seq, memoryview)
    elif isinstance(seq, array.array):
        return (seq, array.array)
    elif isinstance(seq, collections.abc.Sequence):
        return (seq, type(seq))
    else:
        raise TypeError("seq must be a sequence")

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is None:
        return self._scale
    else:
        if not isinstance(other, numbers.Number):
            raise TypeError("Scale must be a number")
        if other <= 0:
            raise ValueError("Scale must be positive")
        if self._scale is None:
            raise LenaValueError("Cannot rescale graph with unknown scale")
        if self._scale == 0:
            raise LenaValueError("Cannot rescale graph with zero scale")
        self._scale = other
        for field in self._fields:
            field.scale(other)
        for error in self._errors:
            error.scale(other)
        return self

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check if the candidate is a class
    if not inspect.isclass(candidate):
        raise TypeError("Candidate must be a class")

    # Check if the candidate has the required interface
    if not all(hasattr(candidate, attr) for attr in iface.__abstractmethods__):
        raise TypeError("Candidate does not have the required interface")

    # If tentative is True, we only need to check that the candidate has the required interface
    if tentative:
        return True

    # Check if the candidate has the required methods
    for method in iface.__abstractmethods__:
        if not hasattr(candidate, method):
            raise TypeError("Candidate does not have the required method")

    # Check if the candidate has the required attributes
    for attr in iface.__abstractmethods__:
        if not hasattr(candidate, attr):
            raise TypeError("Candidate does not have the required attribute")

    # If we reach this point, the candidate has the required interface and methods
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)
    if len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("Inconsistent metaclasses found")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is not __marker:
            return default
        else:
            raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_count = float("inf")
    min_key = None
    for key, (value, count) in self.items():
        if count < min_count:
            min_count = count
            min_key = key

    if min_key is None:
        raise KeyError("popitem(): dictionary is empty")

    value = self[min_key]
    del self[min_key]
    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
        return converter
    except Exception as e:
        raise e

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request.public_message:
            return True
        elif request.private_message:
            return True
        elif request.legacy_payload:
            return True
        else:
            return False
    except Exception as e:
        print(f"Error identifying request: {e}")
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request.headers["Content-Type"] == "application/json":
            data = json.loads(request.body)
            if data["type"] == "matrix":
                return True
        return False
    except (KeyError, ValueError):
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime object")
    return dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        return response.headers.get("Content-Type")
    except requests.exceptions.RequestException:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("Tag must be a string")
    if len(tag) < 1 or len(tag) > 10:
        raise ValueError("Tag must be between 1 and 10 characters long")
    if not tag.isalnum():
        raise ValueError("Tag must contain only letters and digits")
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node.children:
        if child.tag not in result:
            result[child.tag] = []
        result[child.tag].append(child)
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("URL is required")
    if not document_path:
        document_path = ".well-known/nodeinfo"
    nodeinfo = {
        "version": "2.0",
        "software": {
            "name": "Diaspora",
            "version": "1.0"
        },
        "protocols": [
            "activitypub"
        ],
        "services": {
            "inbound": [],
            "outbound": []
        },
        "metadata": {
            "nodeName": "Diaspora Node"
        }
    }
    return nodeinfo

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        json_data = json.loads(document)
        return json_data
    except json.JSONDecodeError:
        pass

    try:
        xrd_data = xml.etree.ElementTree.fromstring(document)
        return xrd_data
    except xml.etree.ElementTree.ParseError:
        pass

    raise ValueError("Invalid Diaspora webfinger format")

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        if response.status_code == 200:
            return response.json()
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        response.raise_for_status()
        data = response.json()
        return {
            "subject": data["subject"],
            "aliases": data["aliases"],
            "links": data["links"],
        }
    except requests.exceptions.RequestException as e:
        raise DiasporaWebfingerError(f"Error retrieving webfinger document for {handle}: {e}") from e
    except (json.JSONDecodeError, KeyError) as e:
        raise DiasporaWebfingerError(f"Error parsing webfinger document for {handle}: {e}") from e

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta.json")
        response.raise_for_status()
        return XRD.from_json(response.json())
    except requests.exceptions.RequestException as e:
        raise DiasporaHostMetaRetrievalError(f"Failed to retrieve host-meta document from {host}") from e

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if not isinstance(val, (str, int, float, bool)):
        raise TypeError("val must be a string, integer, float, or boolean")
    if not isinstance(key, str):
        raise TypeError("key must be a string")
    if not all(isinstance(k, str) for k in keys):
        raise TypeError("all keys in keys must be strings")

    if not keys:
        dic[key] = val
    else:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, *keys)

def ansible_config_manager(cls):
    """Gets the ansible config manager.

    Returns:
        AnsibleConfigManager: The ansible config manager.
    """
    try:
        from ansible.config.manager import ConfigManager
        return ConfigManager()
    except ImportError:
